  "meter": {
    "name": "meter",
    "type": "registry:ui",
    "title": "Meter",
    "description": "Linear and ring measures with threshold tones and readable detail.",
    "categories": [
      "surfaces"
    ],
    "dependencies": [],
    "registryDependencies": [],
    "files": [
      {
        "path": "components/ui/meter.tsx",
        "type": "registry:ui",
        "content": "\"use client\";\n\nimport type { ReactNode } from \"react\";\nimport { injectCss } from \"../../lib/css\";\nimport { clamp, cx } from \"../../lib/utils\";\n\nconst CSS = `\n.ui-meter { display: flex; flex-direction: column; gap: 6px; min-width: 0; }\n.ui-meter__head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 10px;\n  font-size: var(--text-sm);\n  color: var(--ui-ink-soft);\n}\n.ui-meter__label { font-weight: var(--weight-medium); }\n.ui-meter__detail { color: var(--ui-muted); font-variant-numeric: tabular-nums; }\n.ui-meter__track {\n  position: relative;\n  height: 5px;\n  border-radius: var(--ui-r-pill);\n  background: var(--ui-fill);\n  overflow: hidden;\n}\n.ui-meter__fill {\n  position: absolute;\n  inset: 0 auto 0 0;\n  border-radius: inherit;\n  background: var(--ui-solid);\n  transition: width var(--ui-dur-morph) var(--ui-ease-morph), background var(--ui-dur) linear;\n  background-image: linear-gradient(90deg, color-mix(in oklab, currentColor 0%, var(--ui-solid)), var(--ui-solid));\n}\n.ui-meter[data-tone=\"accent\"] .ui-meter__fill { background: var(--ui-accent); }\n.ui-meter[data-tone=\"ok\"] .ui-meter__fill { background: var(--ui-ok); }\n.ui-meter[data-tone=\"warn\"] .ui-meter__fill { background: var(--ui-warn); }\n.ui-meter[data-tone=\"danger\"] .ui-meter__fill { background: var(--ui-danger); }\n.ui-meter__fill[data-striped=\"true\"] {\n  background-image: linear-gradient(\n    90deg,\n    var(--ui-accent) 0 8px,\n    color-mix(in oklab, var(--ui-accent) 55%, transparent) 8px 16px\n  );\n  background-size: 16px 100%;\n}\n\n.ui-ring { position: relative; display: inline-flex; align-items: center; justify-content: center; flex: none; }\n.ui-ring svg { transform: rotate(-90deg); overflow: visible; }\n.ui-ring__track { stroke: var(--ui-fill); }\n.ui-ring__value {\n  stroke: var(--ui-accent);\n  stroke-linecap: round;\n  transition: stroke-dashoffset var(--ui-dur-morph) var(--ui-ease-morph), stroke var(--ui-dur) linear;\n}\n.ui-ring[data-tone=\"solid\"] .ui-ring__value { stroke: var(--ui-solid); }\n.ui-ring[data-tone=\"ok\"] .ui-ring__value { stroke: var(--ui-ok); }\n.ui-ring[data-tone=\"warn\"] .ui-ring__value { stroke: var(--ui-warn); }\n.ui-ring[data-tone=\"danger\"] .ui-ring__value { stroke: var(--ui-danger); }\n.ui-ring__center {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 1px;\n  font-size: var(--text-xs);\n  font-weight: var(--weight-medium);\n  color: var(--ui-ink);\n  font-variant-numeric: tabular-nums;\n  letter-spacing: -0.01em;\n}\n`;\n\ninjectCss(\"ui-meter\", CSS);\n\nexport type MeterTone = \"solid\" | \"accent\" | \"ok\" | \"warn\" | \"danger\";\n\nexport function Meter({\n  value,\n  label,\n  detail,\n  tone = \"solid\",\n  striped,\n  className,\n}: {\n  value: number;\n  label?: ReactNode;\n  detail?: ReactNode;\n  tone?: MeterTone;\n  striped?: boolean;\n  className?: string;\n}) {\n  const pct = clamp(value, 0, 1) * 100;\n  return (\n    <div className={cx(\"ui-meter\", className)} data-tone={tone}>\n      {(label || detail) && (\n        <div className=\"ui-meter__head\">\n          <span className=\"ui-meter__label\">{label}</span>\n          <span className=\"ui-meter__detail\">{detail}</span>\n        </div>\n      )}\n      <div\n        className=\"ui-meter__track\"\n        role=\"progressbar\"\n        aria-valuemin={0}\n        aria-valuemax={100}\n        aria-valuenow={Math.round(pct)}\n        aria-label={typeof label === \"string\" ? label : undefined}\n      >\n        <span\n          className=\"ui-meter__fill\"\n          data-striped={striped || undefined}\n          style={{ width: `${pct}%` }}\n        />\n      </div>\n    </div>\n  );\n}\n\nexport function Ring({\n  value,\n  size = 44,\n  stroke = 4,\n  tone = \"accent\",\n  children,\n  className,\n}: {\n  value: number;\n  size?: number;\n  stroke?: number;\n  tone?: MeterTone;\n  children?: ReactNode;\n  className?: string;\n}) {\n  const radius = (size - stroke) / 2;\n  const circumference = 2 * Math.PI * radius;\n  const pct = clamp(value, 0, 1);\n  return (\n    <div\n      className={cx(\"ui-ring\", className)}\n      data-tone={tone}\n      style={{ width: size, height: size }}\n      role=\"progressbar\"\n      aria-valuemin={0}\n      aria-valuemax={100}\n      aria-valuenow={Math.round(pct * 100)}\n    >\n      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} aria-hidden=\"true\">\n        <circle\n          className=\"ui-ring__track\"\n          cx={size / 2}\n          cy={size / 2}\n          r={radius}\n          fill=\"none\"\n          strokeWidth={stroke}\n        />\n        <circle\n          className=\"ui-ring__value\"\n          cx={size / 2}\n          cy={size / 2}\n          r={radius}\n          fill=\"none\"\n          strokeWidth={stroke}\n          strokeDasharray={circumference}\n          strokeDashoffset={circumference * (1 - pct)}\n        />\n      </svg>\n      {children ? <span className=\"ui-ring__center\">{children}</span> : null}\n    </div>\n  );\n}\n"
      },
      {
        "path": "lib/css.ts",
        "type": "registry:lib",
        "content": "/**\n * One-file components carry their own CSS. `injectCss` puts it in the document\n * exactly once per id, so a component can be copied into any React project as\n * a single file (plus this 12-line helper).\n */\nconst injected = new Set<string>();\n\nexport function injectCss(id: string, css: string): void {\n  if (typeof document === \"undefined\" || injected.has(id)) return;\n  if (document.querySelector(`style[data-copyui=\"${id}\"]`)) {\n    injected.add(id);\n    return;\n  }\n  const tag = document.createElement(\"style\");\n  tag.setAttribute(\"data-copyui\", id);\n  tag.textContent = css;\n  document.head.appendChild(tag);\n  injected.add(id);\n}\n"
      },
      {
        "path": "lib/utils.ts",
        "type": "registry:lib",
        "content": "export function cx(...parts: Array<string | false | null | undefined>): string {\n  return parts.filter(Boolean).join(\" \");\n}\n\nexport function clamp(value: number, min: number, max: number): number {\n  return Math.min(max, Math.max(min, value));\n}\n\n/** \"12s\", \"1m 04s\" — the calm duration format used across agent surfaces. */\nexport function formatDuration(ms: number): string {\n  const total = Math.max(0, Math.round(ms / 1000));\n  if (total < 60) return `${total}s`;\n  const minutes = Math.floor(total / 60);\n  const seconds = total % 60;\n  return `${minutes}m ${String(seconds).padStart(2, \"0\")}s`;\n}\n\n/** 0:42 — the approval countdown. */\nexport function formatClock(seconds: number): string {\n  const s = Math.max(0, Math.ceil(seconds));\n  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, \"0\")}`;\n}\n\nexport function formatMoney(value: number): string {\n  return `$${value.toFixed(2)}`;\n}\n\nexport function initials(name: string): string {\n  return name\n    .split(/\\s+/)\n    .filter(Boolean)\n    .slice(0, 2)\n    .map((part) => part[0]!.toUpperCase())\n    .join(\"\");\n}\n\nconst TINTS = [212, 258, 152, 28, 330, 190, 92];\n\nexport function tintFor(name: string): number {\n  let hash = 0;\n  for (let i = 0; i < name.length; i += 1) hash = (hash * 31 + name.charCodeAt(i)) % 997;\n  return TINTS[hash % TINTS.length]!;\n}\n"
      }
    ]
  },
